        }
    },
    "metadata": {
        "endpoint": "/n/",
        "method": "GET",
        "category": ""
    }
}

{
    "parameters": {
        "location": {
            "type": "str",
            "required": true,
            "description": "City name or coordinates"
        },
        "days": {
            "type": "int",
            "required": false,
            "description": "Number of days for forecast (1-14)"
        },
        "units": {
            "type": "str",
            "required": false,
            "description": "Temperature units: metric or imperial"
        }
    },
    "metadata": {
        "endpoint": "/forecast",
        "method": "GET",
        "category": "weather"
    }
}

{
    "parameters": {
        "to": {
            "type": "list",
            "required": true,
            "description": "List of recipient email addresses"
        },
        "subject": {
            "type": "str",
            "required": true,
            "description": "Email subject line"
        },
        "body": {
            "type": "str",
            "required": true,
            "description": "Email body content"
        },
        "attachments": {
            "type": "list",
            "required": false,
            "description": "List of file URLs to attach"
        },
        "cc": {
            "type": "list",
            "required": false,
            "description": "CC recipients"
        }
    },
    "metadata": {
        "endpoint": "/send",
        "method": "POST",
        "category": "email"
    }
}

{
    "parameters": {
        "image_url": {
            "type": "str",
            "required": true,
            "description": "URL of the image to resize. Supports JPEG, PNG, GIF, WebP formats"
        },
        "width": {
            "type": "int",
            "required": true,
            "description": "Target width in pixels (1-4000)"
        },
        "height": {
            "type": "int",
            "required": true,
            "description": "Target height in pixels (1-4000)"
        },
        "maintain_aspect_ratio": {
            "type": "bool",
            "required": false,
            "description": "Whether to maintain aspect ratio when resizing"
        }
    },
    "metadata": {
        "endpoint": "/resize",
        "method": "POST",
        "category": "image"
    }
}

{
    "parameters": {
        "query": {
            "type": "str",
            "required": true,
            "description": "Search query text"
        },
        "filters": {
            "type": "dict",
            "required": false,
            "description": "Filter criteria including date_range, status, category"
        },
        "sort_by": {
            "type": "str",
            "required": false,
            "description": "Sort field: relevance, created_at, updated_at, or title"
        },
        "limit": {
            "type": "int",
            "required": false,
            "description": "Maximum number of results (1-100)"
        },
        "offset": {
            "type": "int",
            "required": false,
            "description": "Number of results to skip for pagination"
        }
    },
    "metadata": {
        "endpoint": "/query",
        "method": "POST",
        "category": "database"
    }
}
